static void addProduct(List<BigInteger> finite, boolean[] neg, boolean[] pos, BigInteger x, boolean xNeg, boolean xPos, BigInteger y, boolean yNeg, boolean yPos) {
  if (xNeg || xPos || yNeg || yPos) {
     if (x != null && x.signum()==0) { finite.add(BigInteger.ZERO); return; }
     if (y != null && y.signum()==0) { finite.add(BigInteger.ZERO); return; }
     // Determine sign of infinite product
     // If one is inf and other finite nonzero:
     if (xNeg || xPos) {
        if (yNeg || yPos) {
           // both inf
           if ((xNeg && yNeg) || (xPos && yPos)) pos[0]=true; else neg[0]=true;
        } else {
           int s = y.signum();
           if (xNeg) { if (s > 0) neg[0]=true; else pos[0]=true; }
           if (xPos) { if (s > 0) pos[0]=true; else neg[0]=true; }
        }
     } else { // y inf, x finite nonzero
        int s = x.signum();
        if (yNeg) { if (s > 0) neg[0]=true; else pos[0]=true; }
        if (yPos) { if (s > 0) pos[0]=true; else neg[0]=true; }
     }
  } else {
     finite.add(x.multiply(y));
  }
}
