static boolean opPossible(BinOp op, Interval l, Interval r) {
 if (l.empty || r.empty) return false;
 switch(op) {
  case Lt: return !(l.lo != null && r.hi != null && l.lo.compareTo(r.hi) >= 0);
  case Le: return !(l.lo != null && r.hi != null && l.lo.compareTo(r.hi) > 0);
  case Gt: return !(r.lo != null && l.hi != null && r.lo.compareTo(l.hi) >= 0);
  case Ge: return !(r.lo != null && l.hi != null && r.lo.compareTo(l.hi) > 0);
  case Eq: return intervalsIntersect(l,r);
  case Ne: return !(isSingleton(l) && isSingleton(r) && l.lo.equals(r.lo));
  default: return true; // arithmetic? not comparison
 }
}
