static void addProduct(List<BigInteger> finite, boolean[] neg, boolean[] pos,
                       BigInteger x, boolean xNeg, boolean xPos,
                       BigInteger y, boolean yNeg, boolean yPos) {
  if (xNeg || xPos || yNeg || yPos) {
    if (x != null && x.signum() == 0) { finite.add(BigInteger.ZERO); return; }
    if (y != null && y.signum() == 0) { finite.add(BigInteger.ZERO); return; }
    if (xNeg || xPos) {
