        if ((xNeg && yNeg) || (xPos && yPos)) pos[0] = true; else neg[0] = true;
      } else {
        int s = y.signum();
        if (xNeg) { if (s > 0) neg[0] = true; else pos[0] = true; }
        if (xPos) { if (s > 0) pos[0] = true; else neg[0] = true; }
