        Cell c = canonicalize(cell.constraints);
        if (c == null) {
            return bottomState();
        }

        Map<String, Interval> box = propagateBox(c.constraints);
        if (box == null) {
            return bottomState();
        }

        Interval condInt = rvalInterval(cond, box);
        if (condInt.empty || condInt.isZero()) {
            return bottomState();
        }

        return new State(Set.of(c));
    }

