        post = DOMAIN.transfer(new Step.Assume(binop(var("x"), BinOp.Le, intConst(BigInteger.valueOf(5)))), post);

        State pre = DOMAIN.transfer(
                new Step.Call(Optional.of(var("x")), randInt(), List.<RVal>of()),
